+      setError('You must agree to the Terms of Use to continue.');
+      checkbox.focus();
+      return;
+    }
+
+    setError('');
+    statusEl.textContent = 'Thanks — your consent has been recorded.';
+    statusEl.classList.add('success');
+  });
